# Gen AI Prompt Lab projects. Rules score the kid's prompt; replies are SIMULATED (authored), never a live AI.
def C(kind,say,hint,**r):
    if 'not_' in r: r['not']=r.pop('not_')
    return dict(k=kind,say=say,hint=hint,rule=r)
def AP(id,title,emoji,level,themes,hook,problem,learn,scenario,start,checks,best,replies,ask,remix):
    return {'id':id,'kind':'ai','title':title,'emoji':emoji,'level':level,'themes':themes,'hook':hook,'problem':problem,'learn':learn,
      'steps':[{'t':'Read the mission','b':scenario},{'t':'Write your prompt','b':'Type in the box. The checklist ticks as your prompt gets clearer.'},{'t':'Send it to the Practice AI','b':'See how the answer changes when your prompt is better.'}],
      'missions':[{'t':c['say']} for c in checks],'ask':ask,'remix':remix,'showcase':False,'creator':True,
      'ai':{'scenario':scenario,'start':start,'checks':checks,'best':best,'replies':replies}}
A=[]
A.append(AP('ask-like-a-pro','Ask Like a Pro','🌧️',1,['fun'],'Get the Practice AI to explain why it rains, so a 10-year-old gets it.',
 'The AI can only help as much as your prompt lets it. Clear asking is the first skill of every AI builder.',['A prompt = your instruction to the AI','Task + who it is for + how long'],
 'Get the AI to explain why it rains.','Tell me about rain.',
 [C('Task','Say what you want (explain, tell, show).','Start with a clear action word, like Explain.',any=['explain','tell me','describe','why']),
  C('Topic','Mention rain.','Say the topic: rain.',any=['rain']),
  C('Audience','Say who it is for (like a 10-year-old).','Add: for a 10-year-old.',any=['10','kid','child','year-old','year old','primary','class']),
  C('Format','Say how long or what shape (4 short sentences).','Add: in 4 short, simple sentences.',any=['lines','sentence','short','simple','points','steps','words'])],
 'Explain why it rains to a 10-year-old in 4 short, simple sentences.',
 ['Rain is a type of precipitation formed by condensation in the atmosphere when water vapour cools and coalesces into droplets heavy enough to fall.','Rain is water falling from the sky. It happens when water in the air gets cold and turns into drops.','Rain is water falling from clouds. The sun warms water so it goes up as vapour. In the sky it cools and makes drops. When the drops get heavy they fall.','1. The sun warms rivers and puddles. 2. The water floats up as tiny drops. 3. The drops join to make a cloud. 4. When the cloud is full, rain falls. Now you know where rain comes from!'],
 'Ask an adult: what do farmers do in the first rains?','Ask the AI to explain thunder the same way.'))
A.append(AP('inflation-in-kid-words','Inflation in Kid Words','💸',2,['real-world','naija-world'],'Make the AI explain why prices go up, using garri or rice.',
 'Big ideas like inflation need good examples. A great prompt asks for one.',['Asking for an example','Using a place you know'],
 'Get a simple explanation of inflation that a Nigerian 12-year-old understands.','Explain inflation.',
 [C('Topic','Name the topic: inflation or prices going up.','Say inflation or prices.',any=['inflation','prices go up','price']),
  C('Audience','Say who it is for.','Add: for a 12-year-old.',any=['12','10','11','kid','child','year-old','year old','student']),
  C('Local example','Ask for a Nigerian example (garri, rice, naira, market).','Add: use garri or rice as the example.',any=['nigeria','naira','garri','rice','market','yam','bread']),
  C('Format','Say how long (5 simple lines).','Add: in 5 simple lines.',any=['lines','sentence','short','simple','points','steps'])],
 'Explain inflation to a 12-year-old in Nigeria using garri or rice as the example, in 5 simple lines.',
 ['Inflation is a sustained increase in the general price level that reduces purchasing power over time.','Inflation means prices go up. Your money then buys less.','Inflation means prices go up. Last year a cup of rice was cheaper. This year the same money buys less rice.','1. Inflation means prices rise over time.\n2. Last year N500 bought a cup of garri.\n3. This year the same N500 buys a little less.\n4. So your money is worth less.\n5. That is why saving and planning matter.'],
 'Ask an elder: what cost less when you were young?','Ask the AI to explain a price drop (deflation) the same way.'))
A.append(AP('letter-to-the-chairman','Letter to the Chairman','✉️',2,['real-world','naija-world'],'Turn a street problem into a clear, polite letter.',
 'Many people have problems but do not know how to ask for help. A clear prompt makes a clear letter.',['Who, what, where, please','Polite and formal words'],
 'A drain on your street is blocked. Get the AI to draft a letter.','Write a letter.',
 [C('To whom','Say who the letter is for (Chairman, Principal…).','Add: to the Chairman.',any=['chairman','principal','officer','head','mayor','councillor','dear']),
  C('Problem','Say the problem (blocked drain, broken road…).','Add the problem: the blocked drain.',any=['drain','road','water','light','refuse','broken','blocked','problem','gutter']),
  C('Where','Say where it is.','Add: on my street / in my school.',any=['street','community','school','area','town','estate','ilaro','ogun','village']),
  C('Polite ask','Say it must be polite and ask them to fix it.','Add: formal and polite, and ask him to fix it.',any=['polite','formal','respectful','please','request','fix','repair'])],
 "Write a formal and polite letter to the Chairman about the blocked drain on Ayo Street. Ask him to fix it this month.",
 ['Dear Sir/Madam, I am writing to you. Thank you.','Dear Sir, I am writing about a problem. Please help.','Dear Chairman, there is a blocked drain in our area. Please kindly help us. Yours faithfully.','Dear Chairman,\n\nI am writing about the blocked drain on Ayo Street. When it rains, water enters our homes. I respectfully request that you fix it this month.\n\nYours faithfully,\n[Your name]'],
 'Ask: what problem in our community needs a letter?','Ask the AI to write a thank-you letter after the drain is fixed.'))
A.append(AP('my-storybook-page','My Storybook Page','📖',1,['fun','naija-world'],'Ask for a short story with a character, a place and a lesson.',
 'Storybooks need a hero, a place and a point. Tell the AI all three.',['Character + setting + lesson'],
 'Get a short story for younger children.','Write a story.',
 [C('Character','Name a hero (a girl named Ngozi, a tortoise…).','Add: about a girl named Ngozi.',any=['girl','boy','robot','tortoise','farmer','named','called','hero','teacher']),
  C('Place','Say where the story happens.','Add: in a market.',any=['village','market','forest','school','lagos','farm','river','town','city','house']),
  C('Length','Say how long (6 sentences).','Add: in 6 sentences.',any=['sentence','lines','paragraph','words','short']),
  C('Lesson','Ask for a lesson at the end.','Add: end with a lesson about honesty.',any=['lesson','moral','kindness','honest','teach','learn'])],
 'Write a 6-sentence story about a girl named Ngozi in a market who finds a lost wallet. End with a lesson about honesty.',
 ['Once there was a story. It was nice. The end.','Once there was a girl. She did something. She was happy.','Ngozi went to the market. She found a wallet. She was surprised. She took it home.','Ngozi was buying tomatoes in the market when she saw a wallet on the ground. She looked inside and found money and a name card. She ran after the owner and returned it. The owner smiled and thanked her. Ngozi felt proud. Lesson: being honest feels better than keeping something that is not yours.'],
 'Ask a grandparent for a story with a lesson.','Ask the AI for the same story in Nigerian Pidgin.'))
A.append(AP('poster-brief','The Poster Brief','🎨',1,['real-world','fun'],'Describe a poster so clearly that a designer (or AI) could draw it.',
 'AI image tools need a clear brief: what, colours, words and style.',['Describing pictures','Colour, words, style'],
 'Brief an AI designer for a hand-washing poster.','Make a poster.',
 [C('What','Say it is a poster or picture of something.','Say: a poster about washing hands.',any=['poster','image','picture','drawing','flyer']),
  C('Colours','Name the colours.','Add: bright green and yellow.',any=['green','yellow','blue','red','orange','colour','color','bright','purple']),
  C('Words','Give the words on it.','Add the slogan: "Wash your hands".',any=['words','text','slogan','title','says','headline','"',"'"]),
  C('Style','Say the style (cartoon, flat, simple).','Add: cartoon style.',any=['cartoon','style','flat','simple','watercolour','watercolor','bold','funny'])],
 'Make a bright cartoon poster in green and yellow with the slogan "Wash your hands" showing two children at a tap.',
 ['(a random poster appears)','A poster with some hands on it, in some colours.','A cartoon poster in green and yellow showing hands being washed.','Poster plan: cartoon style. Colours: bright green and yellow. Headline: "Wash your hands". Picture: two happy children at a tap with soap bubbles. Small text at the bottom: "20 seconds keeps germs away".'],
 'Look at a poster near you. What 3 things make it easy to read?','Brief a poster for your school club.'))
A.append(AP('spot-the-fib','Ask for Proof','🔎',2,['real-world'],'AI can be wrong. Ask for a source and permission to say "I am not sure".',
 'Good AI users check facts. You can even ask the AI to be honest when it does not know.',['Ask for sources','Allow "I am not sure"'],
 'Ask a fact question the safe way.','How many states?',
 [C('A real question','Ask a clear question (what, who, how many).','Ask: How many states are in Nigeria?',any=['?','what','who','when','how many','which']),
  C('Topic','Say the topic (Nigeria).','Mention Nigeria.',any=['nigeria','state','country','capital','city']),
  C('Source','Ask for a source.','Add: give your source.',any=['source','sources','proof','reference','where did you']),
  C('Honesty','Allow it to say it is not sure.','Add: tell me if you are not sure.',any=["not sure","unsure","don't know","do not know","if you are not","if you aren't"])],
 'How many states are in Nigeria? Give your source, and tell me if you are not sure.',
 ['There are 36.','There are some states in Nigeria.','Nigeria has 36 states and the Federal Capital Territory.','Nigeria has 36 states plus the Federal Capital Territory (Abuja). Source: the Constitution of the Federal Republic of Nigeria. I am confident, but please check with your teacher or an official site.'],
 'Check one AI answer in a book or with a teacher.','Ask for the source of a different fact.'))
A.append(AP('safe-chat-shield','Safe Chat Shield','🛡️',2,['real-world'],'Fix a prompt that gives away private details. Keep the help, lose the risk.',
 'Never put your phone number, address or full name into an AI chat. A smart prompt gets help without sharing them.',['What is private','Ask for help safely'],
 'Rewrite this prompt so it asks for a note to the teacher, but shares NO private details.',
 'My name is Tunde Adeyemi, I live at 12 Ogun Road Ilaro, phone 08012345678. Help me write a note to my teacher about being late.',
 [C('No phone number','Remove the phone number.','Delete the long number.',notRe='\\d{6,}'),
  C('No home address','Remove the home address.','Delete "I live at 12 Ogun Road".',not_=['live at','my address','ogun road','12 ']),
  C('No full name or email','Remove your full name and any email.','Delete "Tunde Adeyemi".',not_=['adeyemi','@','my name is']),
  C('Still asks for help','Keep a clear request (help me write a note to my teacher).','Keep: Help me write a note to my teacher.',any=['teacher'],all=['note'],minWords=5)],
 'Help me write a short, polite note to my teacher saying I will be late tomorrow because of a family matter.',
 ['(Blocked) Your prompt has private details. Remove them first.','(Blocked) Your prompt has private details. Remove them first.','Here is a note. [It may use your private details.]','Dear Teacher,\n\nI am sorry, but I will be late tomorrow because of a family matter. Thank you for understanding.\n\nYours respectfully,\n[Your name]\n\n(Notice: no private details were needed.)'],
 'Ask a parent: what should we never type into a chatbot?','Write a safe prompt for a school project.'))
A.append(AP('study-buddy-coach','Study Buddy Coach','🧠',2,['real-world','fun'],'Make the AI quiz you, one question at a time.',
 'AI can be a patient coach. The trick is telling it HOW to teach.',['Giving the AI a role','One step at a time'],
 'Make the AI your maths coach for fractions.','Teach me maths.',
 [C('Role','Give it a role (teacher, coach, tutor).','Start with: Act as my maths teacher.',any=['teacher','tutor','coach','quiz master','quizmaster','study buddy','act as','you are']),
  C('Topic','Say the topic (fractions…).','Add: on fractions.',any=['fractions','fraction','science','maths','math','english','history','geography','topic','biology','photosynthesis']),
  C('How many','Say how many questions.','Add: 5 questions.',any=['5','five','3','three','10','ten','questions']),
  C('One at a time','Ask it to go one at a time and wait for you.','Add: one at a time, wait for my answer.',any=['one at a time','one by one','wait','after i answer','next question'])],
 'Act as my maths teacher. Quiz me on fractions with 5 questions, one at a time. Wait for my answer before the next.',
 ['Maths is the study of numbers.','Sure. Here are some maths facts.','Here are 5 fraction questions: 1) 1/2+1/2 2) ... (all at once)','Great, I am your maths teacher! Question 1 of 5: What is 1/2 + 1/4? Tell me your answer and I will check it before we go on.'],
 'Ask your teacher: which topic is hardest for the class?','Ask for a quiz on another subject.'))
A.append(AP('translate-with-care','Translate with Care','🗣️',2,['naija-world','fun'],'Get a polite translation and make the AI flag words it is unsure about.',
 'AI can mix up small languages. A careful prompt asks it to be honest about doubts.',['Context matters','Ask for doubts'],
 'Translate "Good morning, sir" for an elder.','Translate good morning.',
 [C('Language','Name the language (Yoruba, Igbo, Hausa, Pidgin, French).','Add: into Yoruba.',any=['yoruba','igbo','hausa','pidgin','french','swahili']),
  C('Ask to translate','Use translate or say.','Say: Translate…',any=['translate','say','how do i say']),
  C('Who for','Say who you are talking to (an elder, a friend).','Add: for an elder.',any=['elder','sir','madam','teacher','friend','respect','polite','formal','greeting']),
  C('Doubts','Ask it to tell you if it is unsure.','Add: tell me if you are not sure of any word.',any=['not sure','unsure','tell me if','mark','doubt'])],
 "Translate 'Good morning, sir' into Yoruba for an elder. Tell me if you are not sure of any word.",
 ['Good morning.','Here is a translation. Hope it helps.','E kaaro, sir. (polite)','E kaaro, sir. (Yoruba, polite, for an elder.) I am fairly sure about this. For Yoruba, please check with a native speaker, because tone marks can change meaning.'],
 'Ask someone to check the translation.','Try a greeting in Igbo.'))
A.append(AP('career-compass-prompt','Career Compass Prompt','🧭',2,['real-world','naija-world'],'Tell the AI what you love and get career ideas with school subjects.',
 'AI gives ideas, not orders. You choose with your family and teachers.',['Telling the AI about you','Asking for reasons'],
 'Get 3 job ideas that fit what you love.','What job should I do?',
 [C('About me','Say what you like or are good at.','Add: I love drawing and puzzles.',any=['i love','i like','i enjoy','interested','good at','my favourite','my favorite']),
  C('Jobs','Ask for jobs or careers.','Ask for jobs.',any=['job','career','work','profession']),
  C('How many','Ask for a number (3).','Add: Suggest 3 jobs.',any=['3','three','5','five','4','four']),
  C('Subjects','Ask which subjects to study.','Add: and the school subjects for each.',any=['subject','learn','study','school','course'])],
 'I love drawing and solving puzzles. Suggest 3 jobs for me and the school subjects I should study for each.',
 ['You should be a doctor.','You could do many jobs.','Jobs: artist, engineer, designer.','1) Graphic designer: Art, Computer Studies. 2) Architect: Maths, Technical Drawing. 3) Software developer: Maths, Computer Studies. These are ideas. Talk to your teachers and family to choose.'],
 'Ask 2 adults how they chose their jobs.','Ask the AI for jobs that did not exist 20 years ago.'))
A.append(AP('fix-the-bad-prompt','Fix the Bad Prompt','🛠️',1,['fun'],'This prompt is lazy. Make it better so you LEARN instead of copying.',
 'Asking AI to do your homework teaches you nothing. Asking it to help you understand does.',['Learning, not copying'],
 'Rewrite "do my homework" into a prompt that teaches you how to divide 24 by 4.','do my homework',
 [C('Learn','Ask it to help you understand or explain.','Start with: Help me understand…',any=['help me understand','explain','teach me','show me how','understand']),
  C('Steps','Ask for steps.','Add: step by step.',any=['step by step','steps','one step']),
  C('My level','Say your class or level.','Add: for a Primary 5 student.',any=['primary','class','jss','ss1','year','grade','student','level']),
  C('Practice','Ask for a practice question.','Add: then give me one practice question.',any=['practice','try one','quiz me','another question','test me'])],
 'Help me understand how to solve 24 divided by 4. Explain it step by step for a Primary 5 student, then give me one practice question.',
 ['The answer is 6.','24 / 4 = 6. Done.','Step 1: Think how many 4s fit in 24. The answer is 6.','Let us work it out! Step 1: How many groups of 4 make 24? Count: 4, 8, 12, 16, 20, 24. That is 6 groups. So 24 ÷ 4 = 6. Your turn: what is 20 ÷ 4?'],
 'Ask your teacher: how can AI help you learn without copying?','Fix another lazy prompt: "write my essay".'))
A.append(AP('idea-to-app-plan','Idea to App Plan','💡',3,['fun','real-world'],'Describe an app so clearly that an AI builder could create it.',
 'Builders "vibe-code" by describing what they want. The clearer you are, the better the app.',['Describing an app','Features and look'],
 'Plan a simple phone website for farmers.','Make an app.',
 [C('What','Say what it is (app, website, game).','Add: a simple phone website.',any=['app','website','site','game','page']),
  C('For whom','Say who it is for.','Add: for farmers.',any=['for farmers','for students','for kids','for traders','for people','for parents','farmers','students','traders']),
  C('Features','List 3 features.','Add: with 3 features: ...',any=['3 features','three features','features','buttons','pages']),
  C('Look','Describe the look.','Add: green colours and big buttons.',any=['colour','color','simple','green','easy','look','design','phone','big buttons'])],
 'Plan a simple phone website for farmers with 3 features: crop calendar, weather tips and a help button. Use green colours and big buttons.',
 ['(builds an app with a lot of random things)','(builds a basic page with no clear purpose)','(builds a farmers page with some features)','Plan: 1) Crop calendar page 2) Weather tips page 3) Help button. Style: green, big buttons, works on phones. Ready to build!'],
 'Ask a farmer: what one thing would help you most?','Describe an app for your own school.'))
